import path from "node:path";
import type { Role } from "./screens";

/**
 * Where each role's saved session lives.
 *
 * Its own module because Playwright refuses to let one TEST file import
 * another, and both `auth.setup.ts` (which writes the state) and
 * `capture.spec.ts` (which reads it) need to agree on the path.
 *
 * Gitignored: these are real session cookies for demo accounts on a dev
 * database, and they are regenerated by the setup project on every run.
 */
export const STATE_DIR = path.resolve(__dirname, "../../.auth");

export const statePath = (role: Role) => path.join(STATE_DIR, `${role}.json`);
